// What the effects run on: Halide kernels (src/halide), each built for the CPU and for the
// GPU APIs of the platform (CMakeLists.txt: ms_kernel), called by name; the images they
// read and write; and ms_run, which runs an effect's kernels on the first API that works
// (macOS: Metal; Linux: CUDA, then Vulkan; Windows: CUDA, then Direct3D 12; then the CPU)
// and keeps their GPU memory between renders.

#pragma once

#include <stddef.h>
#include <stdint.h>

#include "HalideRuntime.h"
#include "kernels.h" // generated by CMakeLists.txt: MsKernel, one MS_K_<NAME> per kernel

typedef enum {
    MS_API_METAL,
    MS_API_CUDA,
    MS_API_VULKAN,
    MS_API_D3D12,
    MS_API_CPU, // last: always available
    MS_API_COUNT,
} MsApi;

// ---------------------------------------------------------------- images

// A width x height image of `channels` floats per pixel, channels next to each other, for
// the kernels (x, y, and channel when channels > 1). Initialised in place (it points to
// itself): never copied.
typedef struct {
    halide_buffer_t b;
    halide_dimension_t dim[3];
    const void *half; // ms_image_rgba in half: the host's pixels, converted by ms_run
    ptrdiff_t half_row;
} MsImage;

// `pixels`: host memory, `row` floats from one row to the next (width x channels when
// packed). The pixels are only read when the image is an input. NULL: an image that only
// lives on the GPU, between two kernels; it needs ms_image_device before its first use.
void ms_image(MsImage *image, const float *pixels, ptrdiff_t row, int width, int height,
              int channels);

// An RGBA image of the host (an effect's input or output): `pixels` in floats, or with
// `half` in 16-bit floats (`row` counts halves then). A half image is a float image for the
// kernels: ms_run converts it on the API it runs on, to float before the kernels (an input)
// or from float after them (the output).
void ms_image_rgba(MsImage *image, const void *pixels, ptrdiff_t row, int half, int width,
                   int height);

// The 16-bit floats themselves (`row` in halves), as two 32-bit integers per pixel (the
// conversion kernels' images).
void ms_image_half(MsImage *image, const void *pixels, ptrdiff_t row, int width, int height);

// A one-channel image holding `*value` at every pixel (strides 0), e.g. the mask value
// without a Mask.
void ms_image_constant(MsImage *image, const float *value, int width, int height);

// Gives `image` GPU memory for `api`: memory kept from earlier renders if some fits (see
// ms_run), else (an image without host memory) new memory. For an image between two kernels
// whose size is only known inside the effect's run function, before its first use. Nothing
// on the CPU. Returns Halide's status (0: success).
int ms_image_device(MsImage *image, MsApi api);

// ---------------------------------------------------------------- kernels

// One argument of a kernel, by the name its generator gives it (src/halide). Build them
// with the macros below.
typedef enum { MS_ARG_IMAGE, MS_ARG_FLOAT, MS_ARG_DOUBLE, MS_ARG_INT } MsArgKind;
typedef struct {
    const char *name;
    MsArgKind kind;
    union {
        MsImage *image;
        float f32;
        double f64;
        int32_t i32;
    };
} MsArg;

#define MS_IMAGE(n, v) ((MsArg){(n), MS_ARG_IMAGE, .image = (v)})
#define MS_FLOAT(n, v) ((MsArg){(n), MS_ARG_FLOAT, .f32 = (float)(v)})
#define MS_DOUBLE(n, v) ((MsArg){(n), MS_ARG_DOUBLE, .f64 = (double)(v)})
#define MS_INT(n, v) ((MsArg){(n), MS_ARG_INT, .i32 = (int32_t)(v)})

// Statuses of ms_kernel besides Halide's own (0: success, negative: a Halide error).
#define MS_KERNEL_NOT_BUILT (-10000) // no version of the kernel for this API
#define MS_KERNEL_BAD_ARGS (-10001)  // arguments that are not the kernel's (printed)

// Runs kernel `k` in its version for `api` with `args`, in any order: each one must be an
// argument of the kernel, with its type, and every argument of the kernel must be given.
// Returns Halide's status (0: success), or one above.
int ms_kernel(MsKernel k, MsApi api, const MsArg *args, int count);

#define MS_KERNEL(k, api, ...)                                                                     \
    ms_kernel((k), (api), (const MsArg[]){__VA_ARGS__},                                            \
              (int)(sizeof((const MsArg[]){__VA_ARGS__}) / sizeof(MsArg)))

// 1 when kernel `k` has a version for `api`.
int ms_kernel_built(MsKernel k, MsApi api);

// ---------------------------------------------------------------- running an effect

// An effect's kernels, in order, on `api`, with `user`'s settings and images. Returns
// Halide's status (0: success), or MS_RUN_DECLINE when the effect does not run on this API
// (e.g. a setting it is slower with there): ms_run then tries the next one.
typedef int (*MsRun)(MsApi api, void *user);
#define MS_RUN_DECLINE (-10002)

// Runs `run` on the first API that works. Before a GPU attempt the `inputs` are marked as
// new in host memory (Halide uploads them); after it the `output` is copied back and the
// GPU memory of all the images is kept for the next renders (where images of the same size
// get it: a new allocation is slow to write the first time), up to 1/16 of the machine's
// memory (at most 2 GB). `between`: the images `run` uses between its kernels; they stay on
// the GPU (those without host memory get GPU memory before `run`, if their size is set).
// An API that does not work here (no driver, no device) is not tried again in this session.
// Returns 1 on success, or 0 with the reason in err; `info` (or NULL) says what it did.
typedef struct MsRunInfo {
    MsApi api;                      // the API it ran on (MS_API_COUNT: none)
    double kernels_ms, download_ms; // the kernels with the uploads of the inputs, then the
                                    // download of the result (0 on the CPU)
    int declined;                   // every API declined (`run` returned MS_RUN_DECLINE)
} MsRunInfo;
int ms_run(MsRun run, void *user, MsImage *const *inputs, int input_count, MsImage *const *between,
           int between_count, MsImage *output, MsRunInfo *info, char *err, size_t err_size);

// Name of `api`, e.g. "Metal"; 1 when a version of the kernels is built for it.
const char *ms_api_name(MsApi api);
int ms_api_built(MsApi api);

// Benchmarks (tools/perf/bench.c): ms_run uses only `api` (MS_API_COUNT: all, the default).
void ms_api_only(MsApi api);

// Benchmarks: page-locks the host's images for the CUDA copies (1, the default) or not.
void ms_pin_host(int on);

// Frees the GPU memory kept for the next renders (the plugin is unloaded).
void ms_engine_shutdown(void);
